### Objective
Build a complete, runnable Multi-Aspect Dashboard Application using custom InheritedModel and StatefulWidget state management, demonstrating selective rebuild isolation across User Profile, Theme Color, and Notification Count.

```dart
import 'package:flutter/material.dart';

void main() {
  runApp(const InheritedModelDemoApp());
}

/// Aspect enum defining the three distinct subscription channels.
enum DashboardAspect { profile, theme, notifications }

/// Root application hosting the InheritedModel state.
class InheritedModelDemoApp extends StatefulWidget {
  const InheritedModelDemoApp({super.key});

  @override
  State<InheritedModelDemoApp> createState() => _InheritedModelDemoAppState();
}

class _InheritedModelDemoAppState extends State<InheritedModelDemoApp> {
  String _userName = 'Arpit Aswal';
  Color _accentColor = Colors.indigo;
  int _unreadNotifications = 3;

  void _updateUser(String newName) => setState(() => _userName = newName);
  void _cycleColor(Color newColor) => setState(() => _accentColor = newColor);
  void _incrementNotifications() => setState(() => _unreadNotifications++);

  @override
  Widget build(BuildContext context)
  {
    return DashboardModel(
      userName: _userName,
      accentColor: _accentColor,
      unreadNotifications: _unreadNotifications,
      onUpdateUser: _updateUser,
      onCycleColor: _cycleColor,
      onIncrementNotifications: _incrementNotifications,
      child: MaterialApp(
        title: 'InheritedModel Aspect Subscriptions',
        debugShowCheckedModeBanner: false,
        theme: ThemeData(
          colorSchemeSeed: _accentColor,
          useMaterial3: true,
        ),
        home: const DashboardHomeScreen(),
      ),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 1. INHERITED MODEL (Aspect-Based Selective Distribution)
// ─────────────────────────────────────────────────────────────────────────────

class DashboardModel extends InheritedModel<DashboardAspect> {
  final String userName;
  final Color accentColor;
  final int unreadNotifications;

  // Action callbacks
  final ValueChanged<String> onUpdateUser;
  final ValueChanged<Color> onCycleColor;
  final VoidCallback onIncrementNotifications;

  const DashboardModel({
    super.key,
    required this.userName,
    required this.accentColor,
    required this.unreadNotifications,
    required this.onUpdateUser,
    required this.onCycleColor,
    required this.onIncrementNotifications,
    required super.child,
  });

  /// Aspect-specific subscription helper for Profile data.
  static DashboardModel ofProfile(BuildContext context) {
    final model = InheritedModel.inheritFrom<DashboardModel>(
      context,
      aspect: DashboardAspect.profile,
    );
    assert(model != null, 'No DashboardModel found in context.');
    return model!;
  }

  /// Aspect-specific subscription helper for Theme data.
  static DashboardModel ofTheme(BuildContext context) {
    final model = InheritedModel.inheritFrom<DashboardModel>(
      context,
      aspect: DashboardAspect.theme,
    );
    assert(model != null, 'No DashboardModel found in context.');
    return model!;
  }

  /// Aspect-specific subscription helper for Notification data.
  static DashboardModel ofNotifications(BuildContext context) {
    final model = InheritedModel.inheritFrom<DashboardModel>(
      context,
      aspect: DashboardAspect.notifications,
    );
    assert(model != null, 'No DashboardModel found in context.');
    return model!;
  }

  /// Read-only accessor without registering any aspect dependency (no rebuilds).
  static DashboardModel read(BuildContext context) {
    final model = context.getInheritedWidgetOfExactType<DashboardModel>();
    assert(model != null, 'No DashboardModel found in context.');
    return model!;
  }

  @override
  bool updateShouldNotify(DashboardModel oldWidget) {
    return userName != oldWidget.userName ||
        accentColor != oldWidget.accentColor ||
        unreadNotifications != oldWidget.unreadNotifications;
  }

  @override
  bool updateShouldNotifyDependent(
    DashboardModel oldWidget,
    Set<DashboardAspect> dependencies,
  ) {
    if (dependencies.contains(DashboardAspect.profile) &&
        userName != oldWidget.userName) {
      return true;
    }
    if (dependencies.contains(DashboardAspect.theme) &&
        accentColor != oldWidget.accentColor) {
      return true;
    }
    if (dependencies.contains(DashboardAspect.notifications) &&
        unreadNotifications != oldWidget.unreadNotifications) {
      return true;
    }
    return false;
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 2. PRESENTATION LAYER (Consuming Screens & Widgets)
// ─────────────────────────────────────────────────────────────────────────────

class DashboardHomeScreen extends StatelessWidget {
  const DashboardHomeScreen({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('InheritedModel Aspect Sandbox'),
        actions: const [
          Padding(
            padding: EdgeInsets.only(right: 16.0),
            child: _NotificationBadgeWidget(),
          ),
        ],
      ),
      body: const Padding(
        padding: EdgeInsets.all(16.0),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            _UserProfileCard(),
            SizedBox(height: 16),
            _ThemeColorCard(),
            SizedBox(height: 16),
            _RebuildDiagnosticSummary(),
            Spacer(),
            _ActionControlsFooter(),
          ],
        ),
      ),
    );
  }
}

/// Rebuild Counter Tracker for diagnostics
class _RebuildCounters {
  static int profileBuilds = 0;
  static int themeBuilds = 0;
  static int notificationBuilds = 0;
}

/// Widget subscribed STRICTLY to DashboardAspect.profile
class _UserProfileCard extends StatelessWidget {
  const _UserProfileCard();

  @override
  Widget build(BuildContext context) {
    final model = DashboardModel.ofProfile(context);
    _RebuildCounters.profileBuilds++;

    return Card(
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Row(
          children: [
            const CircleAvatar(child: Icon(Icons.person)),
            const SizedBox(width: 16),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(model.userName, style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 16)),
                  const Text('Subscribed to: DashboardAspect.profile', style: TextStyle(color: Colors.grey, fontSize: 12)),
                ],
              ),
            ),
            Text('${_RebuildCounters.profileBuilds} builds', style: const TextStyle(color: Colors.blue, fontWeight: FontWeight.bold)),
          ],
        ),
      ),
    );
  }
}

/// Widget subscribed STRICTLY to DashboardAspect.theme
class _ThemeColorCard extends StatelessWidget {
  const _ThemeColorCard();

  @override
  Widget build(BuildContext context) {
    final model = DashboardModel.ofTheme(context);
    _RebuildCounters.themeBuilds++;

    return Card(
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Row(
          children: [
            CircleAvatar(backgroundColor: model.accentColor, radius: 18),
            const SizedBox(width: 16),
            const Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text('Active Theme Accent', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 16)),
                  Text('Subscribed to: DashboardAspect.theme', style: TextStyle(color: Colors.grey, fontSize: 12)),
                ],
              ),
            ),
            Text('${_RebuildCounters.themeBuilds} builds', style: const TextStyle(color: Colors.purple, fontWeight: FontWeight.bold)),
          ],
        ),
      ),
    );
  }
}

/// Widget subscribed STRICTLY to DashboardAspect.notifications
class _NotificationBadgeWidget extends StatelessWidget {
  const _NotificationBadgeWidget();

  @override
  Widget build(BuildContext context) {
    final model = DashboardModel.ofNotifications(context);
    _RebuildCounters.notificationBuilds++;

    return Badge(
      label: Text('${model.unreadNotifications}'),
      child: const Icon(Icons.notifications_outlined),
    );
  }
}

class _RebuildDiagnosticSummary extends StatelessWidget {
  const _RebuildDiagnosticSummary();

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: Colors.grey.shade100,
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: Colors.grey.shade300),
      ),
      child: const Text(
        'Notice: Tapping any button below mutates only one aspect. ' 
        'Because of InheritedModel, elements listening to unaffected aspects ' 
        'completely skip rebuilds!',
        style: TextStyle(fontSize: 13, color: Colors.black87),
      ),
    );
  }
}

class _ActionControlsFooter extends StatelessWidget {
  const _ActionControlsFooter();

  @override
  Widget build(BuildContext context) {
    // Uses read() to avoid subscribing to any rebuilds in the button container
    final model = DashboardModel.read(context);

    return Row(
      mainAxisAlignment: MainAxisAlignment.spaceEvenly,
      children: [
        ElevatedButton.icon(
          onPressed: () => model.onUpdateUser('Arpit Aswal (Lead)'),
          icon: const Icon(Icons.person_outline),
          label: const Text('Update User'),
        ),
        ElevatedButton.icon(
          onPressed: () => model.onCycleColor(Colors.teal),
          icon: const Icon(Icons.palette_outlined),
          label: const Text('Change Theme'),
        ),
        ElevatedButton.icon(
          onPressed: model.onIncrementNotifications,
          icon: const Icon(Icons.add_alert_outlined),
          label: const Text('+1 Notification'),
        ),
      ],
    );
  }
}
```

optimization:
## 1. Use Typed Enums for Aspect Definitions

Always use typed `enum` values or `Symbol`s for aspect identifiers instead of magic strings:
```dart
// GOOD: Compile-time safety and zero typo risk
enum AppAspect { theme, user, cart }

// AVOID: Magic strings prone to silent desynchronization
inheritFrom(context, aspect: 'user_profile');
```

## 2. Guard updateShouldNotify Before Evaluating Aspects

Ensure that `updateShouldNotify` returns `false` if none of the model's properties changed. Flutter will not evaluate `updateShouldNotifyDependent` if `updateShouldNotify` returns `false`, saving CPU cycles across all dependents.

## 3. Leverage read() in Button Handlers

In event callbacks and buttons, call `context.getInheritedWidgetOfExactType` (or expose a static `read()` method). This retrieves the model reference to dispatch callbacks without registering an aspect dependency, keeping button widgets completely free of rebuilds.
